// Player-facing descriptions describe the skill, rather than its development history.
const gold=[
 ['长剑环身旋转，剑气贯穿敌人。','落雷接连轰击敌人，并附加触电与冰冻。','连发追踪毒弹，使敌人中毒并减速。','雷雨连锁轰击敌人，附加触电与冰冻。','陨星接连砸落，点燃敌群。','引力牵引敌人，将其聚拢并撕裂。','寒气直接冻结敌人，抵消袭来的弹丸。'],
 ['朝前方扇形连射冰箭，命中冻结敌人。','朝前方扇形发射贯穿冰晶，连续冻结敌人。','冰晶环身旋转，冻住敌人、挡下弹丸并为穹补盾。'],
 ['枪影环身旋转，贯穿敌人并触发异常暴击。','攻击与冲锋时向八方发射风刃，贯穿敌群。','高速冲锋碾过敌人，击杀后衔接下一次冲锋。'],
 ['旋转轨道光束横扫战场，点燃沿途敌人。','召出灼热恒星，喷涌日珥灼烧敌群。','熔火裂口接连喷发，留下燃烧地带。'],
 ['化身大锤陀螺，曲线追击敌人并甩出旋转锤影。','冰晶巨锤砸落，碎冰斩杀普通与精英敌人，重创首领。','直接冻结敌人，碎冰死亡会将冰冻传给其他敌人。'],
 ['展开随身护盾，庇护穹免受伤害并冻住敌人。','寒潮涌过敌群，造成伤害并冻结敌人。','为队友附上盾印，挡下弹丸并加快技能轮转。'],
 ['药弹命中敌人时治疗穹，溢出治疗转为护盾。','治疗光点守护队伍，恢复穹的生命并加快技能轮转。','连发追踪毒弹，让敌人中毒并减速。'],
 ['雷电丝线连结队友，电击穿过丝线的敌人。','引爆敌人的异常状态，散播毒素并保留异常。','雷柱接连落下，交织触电与冰冻。'],
 ['每次发动，在每位队友脚下召出一把巨剑，同步斩击敌群。','神君巨刃环身轮斩，向外斩出贯穿刀光。','神剑接连插落，以雷击撕裂敌群。'],
 ['史瓦罗导弹接连轰炸，标记敌人供队友集火。','巨型史瓦罗与协同机甲部署防线，扫射敌群。','史瓦罗退场时自爆，歼灭普通与精英敌人，重创首领。'],
 ['成群火流星轰击敌人，留下燃烧陨坑。','双星环身公转，喷出贯穿敌人的星火。','星线连结队友、切割敌人，加快全队技能轮转。'],
 ['吸收亡魂，叠加移动与攻击速度，死蝶环身飞舞。','队友身旁浮现量子残影，接力斩击敌人。','镰刃环身旋转，甩出贯穿敌群的旋转刀痕。']
];
const powers=['','冰箭先冻结目标，再造成伤害。','攻击带异常状态的敌人必定暴击。','炮击点燃敌人，燃烧可触发队友连携。','锤击冰冻目标会散射冰屑，冻结其他敌人。','穹的护盾受击时反击，冻结敌人。','治疗时发射药弹，命中使敌人中毒并减速。','丝线同时施加触电与中毒。','命中异常目标时，闪电传导给其他敌人。','导弹标记敌人，提高全队对其伤害。','火弹点燃敌人，燃烧可触发队友连携。','镰刀与飞刃施加蝶印，队友击杀可触发残影。'];
const synergies=['','穹有护盾时追加冰箭，继承冻结与弹射。','命中异常敌人时扩散减速。','炮击冰冻敌人时引发蒸汽爆发。','锤击将敌人拉近，聚拢给旋转大锤。','消除敌方弹丸，并反射冰箭。','队伍击败中毒敌人时，恢复穹的生命。','异常敌人死亡时，将异常传给其他敌人。','神君与刀光命中时使敌人减速。','导弹穿过目标后继续追踪其他敌人。','燃烧敌人将火焰传给其他敌人。','队友击杀后，残影主动寻找下一个敌人。'];
const hero={sword:'长剑环绕穹旋转，切割接触的敌人。',bullet:'向面朝方向连续发射子弹。',poison:'行走留下毒沼，使敌人中毒并减速。',health:'提高生命上限，获得时恢复生命。',speed:'提升移动速度，加快闪避恢复。',bladeLength:'召出旋转剑，并延长剑刃。',lightning:'闪电在敌人之间跳跃。',meteor:'召来陨星轰击敌人。',pulse:'引力脉冲打击并推开敌人。',frost:'释放寒气，冻住敌人并造成伤害。',leech:'击败敌人积蓄能量，恢复生命。'};
export function installCardCopy(pools){for(const [owner,cards]of Object.entries(pools)){const id=+owner;let n=0;for(const c of cards){let text;
 if(c.gold)text=gold[id][n++];
 else if(!id)text=hero[c.key];
 else if(c.key==='power')text=powers[id];
 else if(c.key==='range')text=synergies[id];
 else if(c.key==='haste')text=id===4?'击败异常敌人加快出招，旋转与移动也更加迅捷。':'击败异常敌人加快出招，技能恢复更快。';
 else if(c.key==='chill')text=[1,4,5,8].includes(id)?'攻击冻住敌人，创造连携机会。':'攻击使敌人减速，创造连携机会。';
 else if(c.key==='execute')text='重创生命低于一半的敌人。';
 else if(c.key==='ward')text=id===5?'重拳击退更有力，并提供更多护盾。':id===9?'召唤史瓦罗时为穹提供护盾。':'治疗时为穹提供护盾。';
 else text={pierce:'冰箭命中后弹向其他敌人。',burn:'炮击留下余火，灼烧敌人。',regen:'治疗后继续为穹恢复生命。',dot:'强化触电，让电流不断侵蚀敌人。',duration:'史瓦罗获得更强的续航能力。'}[c.key];
 if(!text)throw new Error('Missing card copy '+owner+':'+c.key);
 c.describe=r=>text+(r>1?`强化 ${['','Ⅰ','Ⅱ','Ⅲ'][r]}：效果增强。`:'');
 }} }
